<section id="departure-periods"><h2>ช่วงเดินทางและราคาแพ็คเกจส่วนตัว</h2><p>แต่ละการจองเป็นกรุ๊ปส่วนตัว เลือกวันไป–กลับภายในช่วงที่เปิดขาย ราคาต่อคนขึ้นกับระดับบริการและจำนวนผู้เดินทาง</p>
<?php foreach ($available as $dep): $depAnytime=\App\Support\PrivatePackage::anytime($dep); ?><div class="panel"><h3><?= $depAnytime ? 'เดินทางได้ทุกวัน' : e(thai_date($dep['start_date']).' – '.thai_date($dep['end_date'])) ?></h3><p><?= (int)$tour['days'] ?> วัน <?= (int)$tour['nights'] ?> คืน<?= $depAnytime ? ' · จองล่วงหน้าได้ถึง '.e(thai_date($dep['end_date'])) : ' · วันไปและวันกลับอยู่ในช่วงนี้' ?></p><?php if ($depAnytime && !empty($dep['covered'])): ?><p class="fineprint">ทริปที่อยู่ในช่วงพิเศษด้านล่างใช้ราคาของช่วงนั้น</p><?php endif ?><p class="fineprint">จอง จ.–ศ. ก่อน 15:00 น. เดินทางได้ตั้งแต่วันถัดไป · หลัง 15:00 น. เดินทางได้อีก 2 วัน · จอง ส.–อา. เดินทางได้ตั้งแต่วันอังคารถัดไป</p>
<?php $depLevels=[]; foreach (json_decode($dep['private_rates'],true) ?: [] as $rate) { $depLevels[$rate['level']]['rates'][]=$rate; if (trim($rate['details'] ?? '')!=='' && empty($depLevels[$rate['level']]['details'])) $depLevels[$rate['level']]['details']=$rate['details']; } ?>
<div class="table-scroll"><table class="departure-table private-rate-table"><thead><tr><th>จำนวนคน / กรุ๊ป</th><th>ราคาต่อคน</th></tr></thead><?php foreach ($depLevels as $levelName=>$level): usort($level['rates'],static fn($a,$b)=>$a['min'] <=> $b['min']); ?><tbody><tr class="rate-level-row"><th colspan="2" scope="colgroup"><?= e($levelName) ?><?php if (!empty($level['details'])): ?><small class="preline"><?= e($level['details']) ?></small><?php endif ?></th></tr><?php foreach ($level['rates'] as $rate): ?><tr><td><?= people_range($rate['min'],$rate['max']) ?> คน</td><td>฿<?= money($rate['price']) ?></td></tr><?php endforeach ?></tbody><?php endforeach ?></table></div>
<?php $blocked=json_decode($dep['blackout_dates'] ?? '[]',true) ?: []; if ($blocked): ?><p class="fineprint">วันงดเดินทาง: <?= e(implode(', ',array_map('thai_date',$blocked))) ?></p><?php endif ?></div><?php endforeach ?>
<?php if (!$available): ?><p class="notice">ยังไม่มีช่วงเดินทางที่เปิดรับคำขอ</p><?php endif ?></section>
